//! 🧭️ Control lends the actual original authorities to the shared effect settlement owner.
use super::super::NativeEncodeControl;
use crate::{RetainedCloneGrant,RetainedCloneProgress,RetirementDemand,ValueError,ValueRefusalKind};
pub use semio_framework_value_native_outcome::{NativeEncodeEffectSettlement,NativeEncodeEffectPostPhase,NativeEncodeEffectReceipt,NativeEncodeEffectCancellation,NativeEncodeEffectRecovery};
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
impl NativeEncodeControl<'_>{
 /// 🎫️ Captures both original sources and quotes before a caller-owned effect.
 pub fn begin_effect_settlement(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>,demand:RetirementDemand)->Result<bool,ValueError>{self.checkpoint()?;self.begin_effect_settlement_after_checkpoint(slot,demand)}
 fn begin_effect_settlement_after_checkpoint(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>,demand:RetirementDemand)->Result<bool,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).begin(slot,demand)}
 /// 🎟️ Quotes an effect only after the same recorded Source checkpoint succeeds.
 pub fn begin_source_effect_settlement(&mut self,source:crate::OriginalSourceTurnWitness<'_>,marker:&mut super::NativeEncodeEffectProgress<'_>,demand:RetirementDemand,grant:RetainedCloneGrant,local:RetainedCloneProgress)->Result<bool,ValueError>{
  let turn=source.identity();if self.source_turn!=Some(turn){return Err(invalid("original effect Source turn changed"))}if !local.fits(grant)||marker.local_binding.is_some_and(|prior|prior!=(grant,local)){return Err(invalid("original effect local currencies changed"))}*marker.local_binding=Some((grant,local));if marker.checkpoint_ready.is_none(){match self.checkpoint_source(source,marker.checkpoint)?{None=>return Ok(false),Some(Err(error))=>return Err(error),Some(Ok(false))=>return Err(ValueError::literal(ValueRefusalKind::Canceled,"original Source checkpoint canceled")),Some(Ok(true))=>{let ledger=self.ledger.as_ref().ok_or_else(||invalid("original effect ledger absent"))?;*marker.checkpoint_ready=Some((turn,ledger.identity(),self.stage,ledger.owned_bytes(),self.completed,self.total,self.started))}}}let ledger=self.ledger.as_ref().ok_or_else(||invalid("original effect ledger absent"))?;if *marker.checkpoint_ready!=Some((turn,ledger.identity(),self.stage,ledger.owned_bytes(),self.completed,self.total,self.started)){return Err(invalid("original effect checkpoint snapshot changed"))}let allocation=self.scoped_allocation.as_deref_mut().ok_or_else(||invalid("original effect allocation Source absent"))?;let work=self.action.recipient.as_deref_mut().ok_or_else(||invalid("original effect work Source absent"))?;let physical=self.construction.as_deref_mut().ok_or_else(||invalid("original effect construction Source absent"))?;crate::native_receiving::span::progress::validate_source_authorities(source,allocation,work,physical)?;if marker.settlement.is_none(){if *marker.quote_started{return Err(invalid("original effect quote already finished"))}*marker.quote_started=true;return self.begin_effect_settlement_after_checkpoint(marker.settlement,demand)}let state=marker.settlement.as_ref().expect("original settlement retained");if !state.matches_original(self.work_recipient_identity(),self.construction_recipient_identity())||!state.matches_demand(demand){return Err(invalid("original effect Source or demand changed"))}if state.quote_phase()==NativeEncodeEffectPostPhase::Started&&!self.recover_effect_quote(marker.settlement)?{return Ok(false)}if marker.settlement.as_ref().expect("original settlement retained").effect_ready(){return Ok(true)}self.resume_effect_admission(marker.settlement)
 }
 /// 🪢️ Reconciles an interrupted original quote without invoking it a second time.
 /// 🎟️ Reserves the original work after a reconciled quote.
 pub fn recover_effect_quote(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).recover_quote(slot)}
 pub fn resume_effect_admission(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).resume_admission(slot)}
 /// 🪢️ Reconciles a started work-admission callback without replaying it.
 /// ↩️ Returns a reserved action that never performed an effect.
 pub fn cancel_effect_settlement(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<NativeEncodeEffectCancellation,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).cancel(slot)}
 /// ↩️ Releases an unperformed refused original action with the same source loans.
 pub fn release_refused_effect(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<NativeEncodeEffectCancellation,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).release_refused(slot)}
 /// 🧾️ Posts each actual receipt at most once to its original issuer.
 pub fn settle_effect(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity).settle(slot)}
 /// 🪢️ Reconciles the original physical reply without replaying its producer.
 pub fn recover_effect_receipt(&mut self,slot:&mut Option<NativeEncodeEffectSettlement>)->Result<bool,ValueError>{self.settle_effect(slot)}
 /// 🪢️ Reconciles one interrupted callback using the same original authorities without replay.
 /// 👁️ Visits a caller-retained frame while lending its original effect authorities.
 pub fn visit_effect_original<T:Send+'static,O:Send+'static>(&mut self,recipient_identity:u64,visitor:&mut impl FnMut(&mut Option<T>,&mut NativeEncodeEffectRecovery<'_,'_>))->Result<bool,ValueError>{let recipient=self.retirement.as_deref_mut().ok_or_else(||invalid("original effect recovery recipient is absent"))?;if recipient.identity()!=recipient_identity{return Err(invalid("original effect recovery recipient changed"))}let mut recovery=NativeEncodeEffectRecovery::new(&mut self.action,&mut self.construction,self.construction_identity);Ok(crate::ErasedSnapshotRetirement::visit_original(recipient,std::any::TypeId::of::<(T,O)>(),&mut |original|{if let Some(frame)=original.downcast_mut::<Option<T>>(){visitor(frame,&mut recovery)}}))}
}
